<?= $this->extend('layout') ?><?= $this->section('contenido') ?>
<div class="page-head"><div><a class="volver" href="<?= site_url('planificacion') ?>">← Volver a planificación</a><p class="eyebrow">GENERADOR DEL CORE · MÁXIMO 8 PRODUCTOS</p><h1><?= esc($titulo) ?></h1><p class="muted">El pronóstico usa suavización exponencial simple con α = 0.3. El stock se lee del inventario, no del navegador.</p></div></div>
<?php if (isset($errores['productos'])): ?><div class="alerta alerta--error"><?= esc($errores['productos']) ?></div><?php endif; ?>
<section class="card form-card"><form method="post" action="<?= site_url('planificacion/guardar') ?>" class="formulario" id="plan-form"><?= csrf_field() ?><div class="form-grid"><label>Presupuesto del periodo<select name="presupuesto_id" required><option value="">Selecciona un presupuesto</option><?php foreach ($presupuestos as $presupuesto): ?><option value="<?= (int) $presupuesto['id'] ?>" <?= (string) ($datos['presupuesto_id'] ?? '') === (string) $presupuesto['id'] ? 'selected' : '' ?>><?= esc($presupuesto['periodo']) ?> · $<?= number_format((float) $presupuesto['monto_autorizado'], 2) ?></option><?php endforeach; ?></select><small><?= isset($errores['presupuesto_id']) ? esc($errores['presupuesto_id']) : 'La FK se selecciona desde la tabla de presupuestos.' ?></small></label><label>Fecha de corte<input name="fecha_corte" type="date" max="<?= esc(date('Y-m-d'), 'attr') ?>" required value="<?= esc($datos['fecha_corte'] ?? date('Y-m-d'), 'attr') ?>"><small><?= isset($errores['fecha_corte']) ? esc($errores['fecha_corte']) : '' ?></small></label></div><div class="notice"><strong>Relación dependiente activa:</strong> al seleccionar un producto, el dropdown de cotizaciones se carga desde el back-end con ofertas de ese producto que todavía están vigentes. El servidor vuelve a verificar esa relación antes de guardar.</div><div class="plan-rows" id="plan-rows"><?php $filas = $datos['productos'] ?? [['producto_id' => '', 'historial' => '80, 90, 100', 'detalle_cotizacion_id' => '']]; foreach ($filas as $indice => $fila): ?><div class="plan-row"><div class="plan-row__head"><strong>Producto <?= $indice + 1 ?></strong><button class="link-button danger js-remove-row" type="button">Quitar</button></div><div class="form-grid form-grid--three"><label>Producto<select name="producto_id[]" class="js-producto" required><option value="">Selecciona un producto</option><?php foreach ($productos as $producto): ?><option value="<?= (int) $producto['id'] ?>" data-stock="<?= (int) ($saldos[$producto['id']] ?? 0) ?>" <?= (string) ($fila['producto_id'] ?? '') === (string) $producto['id'] ? 'selected' : '' ?>><?= esc($producto['codigo'] . ' · ' . $producto['nombre']) ?></option><?php endforeach; ?></select><small>Stock actual: <span class="js-stock">—</span></small></label><label>Consumos cerrados (3–6)<input name="historial[]" value="<?= esc($fila['historial'] ?? '', 'attr') ?>" placeholder="80, 90, 100" required><small>Separados por coma. Se calcula el pronóstico en PHP.</small></label><label>Cotización vigente<select name="detalle_cotizacion_id[]" class="js-cotizacion" data-selected="<?= esc((string) ($fila['detalle_cotizacion_id'] ?? ''), 'attr') ?>"><option value="">Sin oferta seleccionada</option></select><small>Se filtra por el producto elegido.</small></label></div></div><?php endforeach; ?></div><button class="boton boton--ghost" id="add-row" type="button">＋ Añadir producto al plan</button><div class="form-actions"><a class="boton boton--ghost" href="<?= site_url('planificacion') ?>">Cancelar</a><button class="boton boton--primario" type="submit">Generar borrador <span>→</span></button></div></form></section>
<script>
(() => {
  const rows = document.querySelector('#plan-rows'); const add = document.querySelector('#add-row'); const max = 8;
  const endpoint = '<?= site_url('api/productos') ?>';
  function refresh(row) { const product = row.querySelector('.js-producto'); const quote = row.querySelector('.js-cotizacion'); const stock = row.querySelector('.js-stock'); const id = product.value; stock.textContent = id ? product.options[product.selectedIndex].dataset.stock : '—'; quote.innerHTML = '<option value="">Sin oferta seleccionada</option>'; if (!id) return; quote.innerHTML = '<option value="">Cargando ofertas…</option>'; fetch(endpoint + '/' + id + '/cotizaciones', {headers: {'Accept': 'application/json'}}).then(r => r.json()).then(json => { const selected = quote.dataset.selected; quote.innerHTML = '<option value="">Sin oferta seleccionada</option>'; (json.data || []).forEach(item => { const option = document.createElement('option'); option.value = item.id; option.textContent = item.razon_social + ' · $' + item.precio_unitario + ' · ' + item.cantidad_disponible + ' disponibles'; option.selected = String(item.id) === String(selected); quote.appendChild(option); }); }).catch(() => { quote.innerHTML = '<option value="">No se pudieron cargar ofertas</option>'; }); }
  function bind(row) { row.querySelector('.js-producto').addEventListener('change', () => { row.querySelector('.js-cotizacion').dataset.selected = ''; refresh(row); }); row.querySelector('.js-remove-row').addEventListener('click', () => { if (rows.children.length > 1) row.remove(); }); refresh(row); }
  document.querySelectorAll('.plan-row').forEach(bind);
  add.addEventListener('click', () => { if (rows.children.length >= max) return; const row = rows.firstElementChild.cloneNode(true); row.querySelector('.js-producto').value = ''; row.querySelector('.js-cotizacion').dataset.selected = ''; row.querySelector('.js-cotizacion').innerHTML = '<option value="">Sin oferta seleccionada</option>'; row.querySelector('input[name="historial[]"]').value = '80, 90, 100'; rows.appendChild(row); bind(row); });
})();
</script>
<?= $this->endSection() ?>
